// Ubaci nove prevode u TRANSLATIONS
for (const key in NEW_TRANSLATIONS) {
    for (const lang in NEW_TRANSLATIONS[key]) {
        if (!TRANSLATIONS[lang]) TRANSLATIONS[lang] = {};
        TRANSLATIONS[lang][key] = NEW_TRANSLATIONS[key][lang];
    }
}

